namespace Fanex.Razorbill.Module.Report.Controllers
{
    using System.Web.Mvc;
    using Fanex.Razorbill.Module.Core.Web.Controllers;
    using Fanex.Razorbill.Module.Report.Criteria.Commission;
    using Fanex.Razorbill.Module.Report.Services.Foobet.Impl;
    using Sunplus.Agent.Model.Entities;
    using Fanex.Razorbill.Module.Report.ViewModels.Commission;
    using Fanex.Razorbill.Module.Core.Utils;
    using Fanex.Razorbill.Module.Report.Services.Interface;
    using Fanex.Razorbill.Module.Report.Services.Implement;
    using Fanex.Razorbill.Module.Core.Security;

    public class CommissionByBetTypeController : BaseController
    {
        private readonly ICommissionService _commissionService;
        private readonly IUserSession _userSession;
        private const string MainAction = "Index";

        public CommissionByBetTypeController() :
            this(UserSession.Current, null)
        {
        }

        public CommissionByBetTypeController(IUserSession userSession, ICommissionService commissionService)
        {
            _userSession = userSession;
            this._commissionService = commissionService ?? new CommissionService();
        }

        /// <summary>
        /// Index page.
        /// </summary>
        /// <returns>Index view.</returns>
        [HttpGet]
        public ActionResult Index()
        {
            ViewBag.MinReportDate = Sunplus.Agent.Model.BL.Reports.ReportsBO.BalanceUpDate.ToShortDateString();
            ViewBag.roleId = _userSession.RoleId;
            ViewBag.custId = _userSession.CustId;
            ViewBag.UserTypeAgent = (int)Sunplus.Agent.Model.BL.Definitions.UserTypes.Agent;
            ViewBag.UserTypeMaster = (int)Sunplus.Agent.Model.BL.Definitions.UserTypes.Master;

            return View("~/Areas/Report/Views/CommissionByBetType/Index.cshtml");
        }

        [HttpPost]
        public JsonResult GetCommissionByBettype(CommissionByBettypeCriteria criteria)
        {
            CommissionByBettypeList data = _commissionService.GetCommissionByBettype(criteria);
            Session[CacheServiceKey.SessionKeyCommissionByBettype] = data;
            return Json(new
            {
                data = data,
                roleId = criteria.RoleId
            });
        }

        public ActionResult ExportExcel(CommissionByBettypeCriteria criteria, bool isBold)
        {
            CommissionByBettypeList data = (CommissionByBettypeList)Session[CacheServiceKey.SessionKeyCommissionByBettype];
            var dataStream = _commissionService.ExportExcelCommissionByBettype(criteria, data, isBold);
            if (dataStream != null)
            {
                return File(dataStream.ToArray(), "application/vnd.ms-excel", "CommissionByBettype_" + criteria.FromDate.ToString("MM/dd/yyyy") + "_To_" + criteria.ToDate.ToString("MM/dd/yyyy") + ".xls");
            }
            else
            {
                return new EmptyResult();
            }

        }
    }
}
